export type SectionType = 'header' | 'about' | 'tech-stack' | 'stats' | 'socials' | 'visitors';

export interface BaseSection {
  id: string;
  type: SectionType;
}

export interface HeaderData {
  title: string;
  subtitle: string;
  bannerUrl: string;
  showBanner: boolean;
}

export interface AboutData {
  text: string;
}

export interface TechStackData {
  icons: string[]; // List of devicon class names
}

export interface StatsData {
  username: string;
  showIcons: boolean;
  theme: string;
  hideBorder: boolean;
}

export interface SocialsData {
  github?: string;
  linkedin?: string;
  twitter?: string;
  website?: string;
  email?: string;
}

export interface VisitorData {
  username: string;
  label: string;
  color: string;
  style: 'flat' | 'plastic' | 'flat-square' | 'for-the-badge' | 'social';
}

// Discriminated Union for Section Data
export type SectionData = 
  | HeaderData 
  | AboutData 
  | TechStackData 
  | StatsData 
  | SocialsData
  | VisitorData;

export interface Section extends BaseSection {
  data: any; // Using any for flexibility in the store, but specific components will type check
}

