import { create } from 'zustand';
import { Section, SectionType } from '../types';

interface ReadmeState {
  sections: Section[];
  selectedSectionId: string | null;

  // Actions
  addSection: (type: SectionType) => void;
  removeSection: (id: string) => void;
  updateSection: (id: string, data: any) => void;
  reorderSections: (newSections: Section[]) => void;
  selectSection: (id: string | null) => void;
}

const getDefaultData = (type: SectionType): any => {
  switch (type) {
    case 'header':
      return { 
        title: "Hi 👋, I'm a Developer", 
        subtitle: "A passionate frontend engineer from Earth.", 
        bannerUrl: "https://capsule-render.vercel.app/api?type=waving&color=gradient&height=250&section=header&text=Hello%20World&fontSize=90",
        showBanner: true 
      };
    case 'about':
      return { text: "I love building tools that make developers' lives easier. Currently working on React and AI integration." };
    case 'tech-stack':
      return { icons: ['devicon-javascript-plain', 'devicon-react-original', 'devicon-typescript-plain'] };
    case 'stats':
      return { username: 'facebook', showIcons: true, theme: 'tokyonight', hideBorder: true };
    case 'socials':
      return { github: '', linkedin: '', twitter: '', website: '' };
    case 'visitors':
      return { username: 'yourusername', label: 'Profile Views', color: 'blue', style: 'flat' };
    default:
      return {};
  }
};

export const useReadmeStore = create<ReadmeState>((set) => ({
  sections: [
    { id: '1', type: 'header', data: getDefaultData('header') },
    { id: '2', type: 'tech-stack', data: getDefaultData('tech-stack') },
  ],
  selectedSectionId: '1',

  addSection: (type) => set((state) => {
    const newSection: Section = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      data: getDefaultData(type),
    };
    return { 
      sections: [...state.sections, newSection],
      selectedSectionId: newSection.id 
    };
  }),

  removeSection: (id) => set((state) => ({
    sections: state.sections.filter((s) => s.id !== id),
    selectedSectionId: state.selectedSectionId === id ? null : state.selectedSectionId
  })),

  updateSection: (id, data) => set((state) => ({
    sections: state.sections.map((s) => 
      s.id === id ? { ...s, data: { ...s.data, ...data } } : s
    )
  })),

  reorderSections: (newSections) => set({ sections: newSections }),

  selectSection: (id) => set({ selectedSectionId: id }),
}));

import { Section } from '../types';

export const generateMarkdown = (sections: Section[]): string => {
  let markdown = '';

  sections.forEach((section) => {
    const { type, data } = section;

    switch (type) {
      case 'header':
        if (data.showBanner && data.bannerUrl) {
          markdown += `![Header](${data.bannerUrl})\n\n`;
        }
        markdown += `# ${data.title}\n\n`;
        if (data.subtitle) markdown += `### ${data.subtitle}\n\n`;
        break;

      case 'about':
        markdown += `${data.text}\n\n`;
        break;

      case 'tech-stack':
        markdown += `### 🛠️ Languages and Tools\n\n`;
        markdown += `<p align="left">\n`;
        data.icons.forEach((iconClass: string) => {
          // Mapping devicon class to actual URL (since devicon classes are CSS based, for MD we need SVG urls)
          // Using a reliable CDN for devicon SVGs
          const iconName = iconClass.replace('devicon-', '').split('-')[0];
          // This is a rough heuristic, for a production app we'd need a map of class -> url
          const url = `https://cdn.jsdelivr.net/gh/devicons/devicon/icons/${iconName}/${iconName}-original.svg`;
          markdown += `  <a href="https://skillicons.dev" target="_blank" rel="noreferrer"> <img src="${url}" alt="${iconName}" width="40" height="40"/> </a> \n`;
        });
        markdown += `</p>\n\n`;
        break;

      case 'stats':
        markdown += `### ⚡ Stats\n\n`;
        markdown += `![Stats](https://github-readme-stats.vercel.app/api?username=${data.username}&show_icons=${data.showIcons}&theme=${data.theme}&hide_border=${data.hideBorder})\n\n`;
        markdown += `![Streak](https://github-readme-streak-stats.herokuapp.com/?user=${data.username}&theme=${data.theme}&hide_border=${data.hideBorder})\n\n`;
        break;

      case 'socials':
        markdown += `### 📫 Connect with me\n\n`;
        markdown += `<p align="left">\n`;
        if (data.github) markdown += `  <a href="${data.github}" target="_blank"><img src="https://img.shields.io/badge/Github-181717?style=for-the-badge&logo=github&logoColor=white" alt="Github" /></a>\n`;
        if (data.linkedin) markdown += `  <a href="${data.linkedin}" target="_blank"><img src="https://img.shields.io/badge/LinkedIn-0077B5?style=for-the-badge&logo=linkedin&logoColor=white" alt="LinkedIn" /></a>\n`;
        if (data.twitter) markdown += `  <a href="${data.twitter}" target="_blank"><img src="https://img.shields.io/badge/Twitter-1DA1F2?style=for-the-badge&logo=twitter&logoColor=white" alt="Twitter" /></a>\n`;
        if (data.website) markdown += `  <a href="${data.website}" target="_blank"><img src="https://img.shields.io/badge/Website-000000?style=for-the-badge&logo=About.me&logoColor=white" alt="Website" /></a>\n`;
        markdown += `</p>\n\n`;
        break;

      case 'visitors':
        markdown += `![Visitors](https://visitor-badge.laobi.icu/badge?page_id=${data.username}.${data.username}&left_text=${data.label}&color=${data.color}&style=${data.style})\n\n`;
        break;
    }
  });

  return markdown;
};

