    </div>
  );
};

const VisitorRenderer: React.FC<RendererProps> = ({ section }) => {
    const { username, label, color, style } = section.data;
    if(!username) return <div className="text-slate-500">Configure username</div>;
    const url = `https://visitor-badge.laobi.icu/badge?page_id=${username}.${username}&left_text=${label}&color=${color}&style=${style}`;
    return (
        <div>
            <img src={url} alt="visitors" />
        </div>
    )
}

export const renderSection = (section: Section) => {
  switch (section.type) {
    case 'header': return <HeaderRenderer section={section} />;
    case 'about': return <AboutRenderer section={section} />;
    case 'tech-stack': return <TechStackRenderer section={section} />;
    case 'stats': return <StatsRenderer section={section} />;
    case 'socials': return <SocialsRenderer section={section} />;
    case 'visitors': return <VisitorRenderer section={section} />;
    default: return <div>Unknown Component</div>;
  }
};

import React, { useState } from 'react';
