    const md = generateMarkdown(sections);
    navigator.clipboard.writeText(md);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const md = generateMarkdown(sections);
    const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
