              <div>
                <label className="text-xs uppercase text-slate-500 font-bold">Subtitle</label>
                <textarea 
                  className="w-full bg-slate-800 border border-slate-700 rounded p-2 text-white mt-1 focus:border-primary-500 outline-none"
